// Rebuilds src/lib/machines.generated.ts after adding or removing a file in content/machines.
import { readdirSync, writeFileSync } from "node:fs";

const slugs = readdirSync(new URL("../content/machines", import.meta.url))
  .filter((file) => file.endsWith(".json"))
  .map((file) => file.slice(0, -5))
  .sort();
const ident = (slug) => "m_" + slug.replace(/\W/g, "_");
const lines = [
  "// Generated by scripts/build-machine-index.mjs — one import per file in content/machines.",
  'import type { Machine } from "./content";',
  ...slugs.map((slug) => `import ${ident(slug)} from "@content/machines/${slug}.json";`),
  "",
  "export const machineIndex = {",
  ...slugs.map((slug) => `  "${slug}": ${ident(slug)},`),
  "} as unknown as Record<string, Machine>;",
  "",
];
writeFileSync(new URL("../src/lib/machines.generated.ts", import.meta.url), lines.join("\n"));
console.log(`${slugs.length} machines indexed`);
